// Independent check of the solver: for positions reached by random play from the opening, the
// value in the table must follow from its children's values, with the children generated by the
// JavaScript engine (not by the solver). Usage: node check_table.mjs table.bin [games]
import { initialState, legalMoves, step, MINT, CORAL } from '../engine.js';
import { loadTable, index, kind, plies } from './table.mjs';

const T = loadTable(process.argv[2]);
const games = +(process.argv[3] || 3000);
let seed = 12345;
const rnd = (n) => { seed = (seed * 1103515245 + 12345) >>> 0; return seed % n; };

let checked = 0, bad = 0;
const counts = { win: 0, loss: 0, draw: 0 };
// what each move is worth to the mover: { now: true } for a win at once, else the child's value
function children(s) {
  return legalMoves(s).map((m) => {
    const c = step(s, m);
    if (c.reason === 'target') return { now: true };
    const w = T[index(c)];
    if (c.reason === 'stuck' && w !== 3) bad++;          // the solver counts a stuck side as lost in 1
    return { w };
  });
}
function check(s) {
  const v = T[index(s)], kids = children(s);
  let ok;
  const winsNow = kids.some((k) => k.now);
  const losses = kids.filter((k) => !k.now && k.w & 1).map((k) => plies(k.w));      // child loses: we win
  if (v === 0) ok = !winsNow && !losses.length && kids.some((k) => k.w === 0);
  else if (v & 1) ok = !winsNow && kids.every((k) => k.w && !(k.w & 1)) && Math.max(...kids.map((k) => plies(k.w) + 1)) === plies(v);
  else {
    const best = winsNow ? 1 : Math.min(...losses) + 1;
    ok = best === plies(v);
  }
  checked++; counts[kind(v)]++;
  if (!ok) { bad++; if (bad < 5) console.log('mismatch', s.towers.join(','), s.sun, s.turn, v, JSON.stringify(kids)); }
}
for (let g = 0; g < games; g++) {
  let s = initialState(g % 2 ? CORAL : MINT);
  for (let ply = 0; ply < 120 && s.winner === null; ply++) {
    check(s);
    const ms = legalMoves(s);
    s = step(s, ms[rnd(ms.length)]);
  }
}
console.log(`checked ${checked} positions (win ${counts.win}, loss ${counts.loss}, draw ${counts.draw}); mismatches ${bad}`);
console.log('opening:', kind(T[index(initialState(MINT))]), 'with Mint first,', kind(T[index(initialState(CORAL))]), 'with Coral first');
process.exitCode = bad ? 1 : 0;
